arget="#statusModal" data-id="{{$r->id}}" data-status="{{$r->status}}" data-rating="{{$r->rating}}" data-comments="{{$r->comments}}" onclick="statusER(this)" title="Update"><svg viewBox="0 0 24 24"><path d="M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7"/></svg></button><form method="POST" action="{{route('employee-reviews-destroy',$r)}}" class="er-delete">@csrf @method('DELETE')<button title="Delete"><svg viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m5 4v7m4-7v7"/></svg></button></form></div></td></tr>@empty<tr><td colspan="8" class="text-center text-muted py-10">No employee reviews found.</td></tr>@endforelse</tbody></table></div><div class="d-flex justify-content-between p-4"><span class="text-muted">Showing {{$reviews->firstItem()??0}} to {{$reviews->lastItem()??0}} of {{$reviews->total()}} results</span>{{$reviews->links('pagination::bootstrap-4')}}</div></div></div>
<div class="modal fade" id="statusModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="statusForm" method="POST" novalidate>@csrf @method('PATCH')<div class="modal-header"><h3>Update Review Status</h3><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-5"><label class="form-label required">Status</label><select class="form-select" name="status" onchange="reviewFields(this.value)"><option>Scheduled</option><option>In Progress</option><option>Completed</option></select></div><div id="completedFields"><div class="mb-5"><label class="form-label required">Overall Rating</label><input class="form-control" type="number" name="rating" min="0" max="5" step="0.1" placeholder="0.0 - 5.0"></div><div><label class="form-label">Comments</label><textarea class="form-control" name="comments" rows="4"></textarea></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success">Save</button></div></form></div></div></div>
<script>const statusUrl=@json(route('employee-reviews-status','__ID__'));function statusER(b){let f=statusForm;f.action=statusUrl.replace('__ID__',b.dataset.id);f.elements.status.value=b.dataset.status;f.elements.rating.value=b.dataset.rating||'';f.elements.comments.value=b.dataset.comments||'';reviewFields(b.dataset.status)}function reviewFields(v){completedFields.style.display=v==='Completed'?'block':'none'}document.addEventListener('DOMContentLoaded',()=>{statusForm.onsubmit=e=>{if(statusForm.elements.status.value==='Completed'&&!statusForm.elements.rating.value){e.preventDefault();Swal.fire({icon:'error',text:'Overall Rating is required for a completed review'})}};document.querySelectorAll('.er-delete').forEach(f=>f.onsubmit=e=>{if(f.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete employee review?',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f1416c'}).then(r=>{if(r.isConfirmed){f.dataset.ok=1;f.submit()}})})})</script>@endsection
